import React from 'react';
import { FaMoon, FaSun, FaBars } from 'react-icons/fa';
import { UserButton, useUser } from '@clerk/clerk-react';
import './Header.css';

const Header = ({ darkMode, toggleDarkMode, toggleSidebar, currentPage }) => {
  const { user } = useUser();

  // Convert page ID to title case for display
  const formatPageTitle = (page) => {
    if (page === 'home') return 'Dashboard';
    return page.charAt(0).toUpperCase() + page.slice(1);
  };

  return (
    <header className="app-header">
      {/* Left: Menu button + Page title */}
      <div className="header-left">
        <button className="menu-btn" onClick={toggleSidebar}>
          <FaBars size={20} />
        </button>
        <div className="page-info">
          <h2 className="current-page-title">{formatPageTitle(currentPage)}</h2>
        </div>
      </div>

      {/* Right: User controls */}
      <div className="header-right">
        <span className="user-info">
          Welcome, {user?.firstName} {user?.lastName}
        </span>
        <span className="login-btn">
          <UserButton />
        </span>
        <span
          className="darkmode-toggle"
          onClick={toggleDarkMode}
          title="Toggle Dark Mode"
          role="button"
          tabIndex={0}
        >
          {darkMode ? <FaSun size={22} /> : <FaMoon size={22} />}
        </span>
      </div>
    </header>
  );
};

export default Header;
